Definition dealloc_post (sp gp tp s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (lo U size b1 actx TH : Z) (T : list Z) (d : depot) : machine_state -> Prop :=
  fun ms' => exists (t0 t1 t2 a6 a7 t3 t4 t5 t6 : word) m',
    ms' = MS (mkR (wz 0x0746f8) (Z_to_bv 64 (bv_unsigned sp + -2128)) gp tp t0 t1 t2 sp (wz U)
                  (wz (AINST + OI_Q)) (wz (TH + OT_TQ)) (wz (TH + OT_CACHE)) (Z_to_bv 64 (bv_unsigned sp + -2128)) (wz (U + -16)) (wz size) a6 a7
                  (wz 0x074688) (wz 1) (Z_to_bv 64 (bv_unsigned sp + -2128)) (Z_to_bv 64 (bv_unsigned sp + -81)) s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 0x54480) fc None m' (seg_rom bsegs)
    /\ munch ([(lo, bv_unsigned sp + -2128); (U + -16, U + -12); (U, U + 8); (TH + 2800, TH + 3168)] ++ depot_W d) m m'
    /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp + -2128)
    /\ rw_cells bsegs m' (U + -16) [C1 (b8 3); C1 (b8 b1); C2 (wz 0); C4 (wz size); C8 (wz actx)]
    /\ rw_cells bsegs m' U [C8 (wz (d_putid d (depot_hash T)))]
    /\ stk bsegs m' (TH + 2800) (TH + 3168)
    /\ DEPOT bsegs (d_put d (depot_hash T) (Z.of_nat (length T))) m'.

