  Lemma dealloc_cas : forall (x1 : word) (t0 t1 t2 xa0 xa1 xa2 xa3 xa4 xa5 xa6 xa7 t3 t4 t5 t6 xs0 xs1 xs3 xs4 xs5 xs6 : word) m0 (Q : machine_state -> Prop),
    mem_inv bsegs m0 ->
    rw_cells bsegs m0 (U + -16) [C1 (b8 2); C1 (b8 b1); C2 (wz 0); C4 (wz size); C8 (wz actx)] ->
    (forall (ya0 ya1 ya2 ya3 ya4 ya5 ya6 ya7 : word) m1,
        mem_inv bsegs m1 -> munch [(U + -16, U + -12)] m0 m1 -> wmono bsegs m0 m1 ->
        rw_cells bsegs m1 (U + -16) [C1 (b8 3); C1 (b8 b1); C2 (wz 0); C4 (wz size); C8 (wz actx)] ->
        evt bsegs Q (MS (mkR x1 (Z_to_bv 64 (bv_unsigned sp + -2192)) gp tp t0 t1 t2 xs0 xs1 ya0 ya1 ya2 ya3 ya4 ya5 ya6 ya7
                          (wz (U + -16)) xs3 xs4 xs5 xs6 s7 s8 s9 s10 s11 t3 t4 t5 t6) F (Z_to_bv 64 0x4fe70) fc None m1 (seg_rom bsegs))) ->
