  Theorem dealloc_seg :
    IENV tp TSD CTX TH sb TOP BOT m -> mem_inv bsegs m -> stk bsegs m lo (bv_unsigned sp + -2128) ->
    rw_cells bsegs m (U + -16) [C1 (b8 2); C1 (b8 b1); C2 (wz 0); C4 (wz size); C8 (wz actx)] ->
    rw_cells bsegs m U [CB 8 ub] ->
    stk bsegs m (TH + 2800) (TH + 3168) ->
    rw_cells bsegs m (bv_unsigned sp + -2128) [C8 (wz (bv_unsigned sp + -2128 + 16)); C8 (wz (Z.of_nat (length T)))] ->
    u64arr bsegs m (bv_unsigned sp + -2128 + 16) (map wz T ++ rest) ->
    DEPOT bsegs d m ->
    evt bsegs POST
      (MS (mkR (wz 0x0746f8) (Z_to_bv 64 (bv_unsigned sp + -2128)) gp tp x3 x4 x5 sp a0 (wz AINST) a0 (wz 0) (wz 0)
               (Z_to_bv 64 (bv_unsigned sp + -2128)) (wz 1) x12 x13 (wz 0x074688) (wz 1)
               (Z_to_bv 64 (bv_unsigned sp + -2128)) (Z_to_bv 64 (bv_unsigned sp + -81)) s6 s7 s8 s9 s10 s11 x14 x15 x16 x17)
